def rows_in(text):
    out = []
    for m in ROWLIST.finditer(text):
        body = m.group(1)
        nums = [int(x) for x in re.findall(r'\d{1,3}', body)]
        for a, b in re.findall(r'(\d{1,3}) (?:to|through) (\d{1,3})', body):
            a, b = int(a), int(b)
            if 0 < b - a < 40:
                nums += list(range(a, b + 1))
        for n in sorted(set(nums)):
            out.append((n, m.start(), m.end()))
    return out

FIXWORD = re.compile(r'\b(fix(?:ed|es)?|repair(?:ed|s)?|clos(?:ed|es)|clears?|cleared|resolved|no longer|promoted|retired|gone|duplicates?)\b', re.I)
